INSERT INTO public."AuditLog" VALUES ('8d07bc51-7320-43f4-b695-404d9dfd4316', '7b93f413-f30d-4852-90f3-ac82fa7390ae', 'UPDATE', 'FinishedProduct', '976f7e24-b7a0-4993-8c98-4287b8653a9f', '{"id": "976f7e24-b7a0-4993-8c98-4287b8653a9f", "cgst": 2.5, "code": "FP-000001", "igst": 5, "name": "Vanilla Ice Cream Cup (100 ml)", "sgst": 2.5, "unitId": "67c5b50b-20fb-4978-b5a2-dfe366a93949", "imageUrl": "data:image/jpeg;base64,", "sopSteps": [{"tempTime": "10–15 minutes", "safetyNote": "Wear gloves, hairnet, face mask, and apron. Ensure all mixing equipment is clean and sanitized.", "stepNumber": 1, "instruction": "Mix skimmed milk, granulated sugar, and vanilla extract until the ingredients are fully blended."}, {"tempTime": "80–85°C for 15 seconds, then cool to 4°C for 4–12 hours", "safetyNote": "Hazard: Hot surfaces and steam may cause burns. Use heat-resistant gloves and follow food safety procedures.", "stepNumber": 2, "instruction": "Pasteurize the mixture, then cool and age it before freezing."}, {"tempTime": "Freeze at -5°C to -7°C, then harden at -18°C for 6–12 hours", "safetyNote": "Hazard: Cold surfaces may cause cold burns and slippery floors. Wear insulated gloves, safety shoes, and maintain a clean, dry work area.", "stepNumber": 3, "instruction": "Freeze the mixture, fill into plastic cups, seal with lids, and harden before storage."}], "createdAt": "2026-07-01T10:30:51.364Z", "createdBy": "7b93f413-f30d-4852-90f3-ac82fa7390ae", "deletedAt": null, "salePrice": 30, "totalCost": 8.26, "updatedAt": "2026-07-01T10:30:51.364Z", "alertLevel": 20, "categoryId": "9f481081-b324-46c0-a710-199b7c5212eb", "sopHistory": null, "isSopLocked": true, "stockMethod": "FIFO", "currentStock": 100, "openingStock": 100, "profitMargin": 0, "expectedOutput": 1, "totalRawMaterialCost": 8.26, "totalNonInventoryCost": 0}', '{"id": "976f7e24-b7a0-4993-8c98-4287b8653a9f", "cgst": 2.5, "code": "FP-000001", "igst": 5, "name": "Vanilla Ice Cream Cup (100 ml)", "sgst": 2.5, "unitId": "67c5b50b-20fb-4978-b5a2-dfe366a93949", "imageUrl": "data:image/jpeg;base64,", "sopSteps": [{"tempTime": "10–15 minutes", "safetyNote": "Wear gloves, hairnet, face mask, and apron. Ensure all mixing equipment is clean and sanitized.", "stepNumber": 1, "instruction": "Mix skimmed milk, granulated sugar, and vanilla extract until the ingredients are fully blended."}, {"tempTime": "80–85°C for 15 seconds, then cool to 4°C for 4–12 hours", "safetyNote": "Hazard: Hot surfaces and steam may cause burns. Use heat-resistant gloves and follow food safety procedures.", "stepNumber": 2, "instruction": "Pasteurize the mixture, then cool and age it before freezing."}, {"tempTime": "Freeze at -5°C to -7°C, then harden at -18°C for 6–12 hours", "safetyNote": "Hazard: Cold surfaces may cause cold burns and slippery floors. Wear insulated gloves, safety shoes, and maintain a clean, dry work area.", "stepNumber": 3, "instruction": "Freeze the mixture, fill into plastic cups, seal with lids, and harden before storage."}], "createdAt": "2026-07-01T10:30:51.364Z", "createdBy": "7b93f413-f30d-4852-90f3-ac82fa7390ae", "deletedAt": null, "salePrice": 30, "totalCost": 8.26, "updatedAt": "2026-07-01T10:46:50.319Z", "alertLevel": 20, "categoryId": "9f481081-b324-46c0-a710-199b7c5212eb", "sopHistory": null, "isSopLocked": true, "stockMethod": "FIFO", "currentStock": 125, "openingStock": 100, "profitMargin": 0, "expectedOutput": 1, "totalRawMaterialCost": 8.26, "totalNonInventoryCost": 0}', '::1', '2026-07-01 10:46:50.34') ON CONFLICT DO NOTHING;
INSERT INTO public."AuditLog" VALUES ('0a132250-b218-46d2-a3ab-af5e46bbbf81', '7b93f413-f30d-4852-90f3-ac82fa7390ae', 'UPDATE', 'CustomerOrder', '6228d1bf-0d61-4ef1-acff-c23553c7bf3e', '{"id": "6228d1bf-0d61-4ef1-acff-c23553c7bf3e", "cgst": 68.85, "igst": 0, "sgst": 68.85, "type": "Sales Order", "status": "In Production", "freight": 20, "taxType": "Exclusive", "otherGst": true, "roundOff": 0.2999999999999545, "taxRegNo": "33AAFFT0634G1ZJ", "createdAt": "2026-07-01T10:44:30.530Z", "createdBy": "7b93f413-f30d-4852-90f3-ac82fa7390ae", "deletedAt": null, "insurance": 10, "totalCost": 206.5, "updatedAt": "2026-07-01T10:45:22.090Z", "collectTax": true, "customerId": "c126bcd0-34e7-4da1-91c3-5d0f207ef1da", "freightGst": true, "grandTotal": 898, "loadingGst": true, "packingGst": true, "referenceNo": "CO-000001", "totalProfit": 543.5, "deliveryDate": "2026-07-01T00:00:00.000Z", "insuranceGst": true, "internalNote": null, "otherCharges": 20, "paymentTerms": "Paid", "tdsDeduction": 5, "discountValue": 10, "quotationNote": "1. Acceptance of Order: The vendor must confirm acceptance of the Purchase Order (PO) in writing via email or signed acknowledgment within 03 working days from the date of issue. If no written confirmation is received within this window, the Buyer reserves the right to cancel the order without any financial liability.\n2. Price and Taxes: Prices stated in this PO are firm, fixed, and non-escalating. Prices are inclusive of all packing, forwarding, freight, transit insurance, and handling charges up to the delivery site. All taxes, specifically GST, must be clearly itemized on the invoice in strict accordance with CGST, SGST, and IGST rules. Any future tax benefits or Input Tax Credit (ITC) changes must be passed on to the Buyer.\n3. Warranty: The Vendor warrants that all supplied goods are brand new, genuine, and free from defects in material and workmanship for 12 months from the date of acceptance. For services, the Vendor guarantees performance by qualified personnel matching industry standards. Any defective goods or substandard services identified within this period must be replaced, repaired, or re-performed by the Vendor within 7 business days at no additional cost to the Buyer.\n4. Billing Instructions: Invoices must be raised as statutory Tax Invoices clearly bearing the Vendor’s valid GSTIN, correct HSN/SAC codes, and the exact Buyer PO number. Delayed submission of invoices or failure to upload invoice data to the GST portal (preventing the Buyer from claiming Input Tax Credit) will directly result in a corresponding delay in payment processing.\n5. Payment Terms: Payment shall be processed via electronic transfer (NEFT/RTGS) split across two strict milestones: 50% Advance Payment: Processed within 7 working days upon written confirmation and formal acceptance of the Purchase Order (PO) by the Vendor, against the submission of a valid Proforma Invoice. 50% Final Payment: Processed within 45 days from the date of successful physical delivery of all materials at the designated site. This is subject to the submission of complete, error-free documents (Tax Invoice, Delivery Challan, and validated E-way Bill) and physical inspection and acceptance of the defect-free materials by the Buyer''s site team.\n6. Delivery & Liquidated Damages (LD): The delivery timeline starts immediately upon the Vendor''s receipt of the 50% advance payment and must be completed strictly within 25Days. Failure to deliver on time will result in a penalty of 0.5% of the total PO value per week of delay, capped at 10%. Exceeding this 10% limit gives the Buyer the right to terminate the contract immediately and source elsewhere at the Vendor''s expense.\n7. Quality & Inspection: All deliverables must strictly match the technical specifications mentioned in the PO. The Buyer reserves the right to inspect materials upon arrival at the site. The Buyer can reject any defective, damaged, or substandard items. Rejected goods must be collected and removed by the Vendor from the Buyer''s premises within 7 days of rejection notification at the Vendor''s sole risk and expense.\n8. Statutory Compliance: The Vendor shall strictly comply with all applicable Central, State, and local government laws, labor regulations (including Provident Fund, ESIC, and Minimum Wages acts), and anti-bribery policies. The use of child labor is strictly prohibited. The Vendor is solely responsible for generating accurate E-way bills for all transit movements.\n9. Dispute Resolution: Any dispute arising out of this PO shall first be resolved through amicable mutual discussions. Unresolved disputes shall be referred to a sole arbitrator appointed mutually by both parties, governed by the Indian Arbitration and Conciliation Act, 1996. The venue and seat of arbitration shall be Tamil Nadu, and proceedings will be conducted in English. The courts in Salem shall have exclusive jurisdiction over this contract.", "totalSubtotal": 750, "loadingCharges": 20, "packingCharges": 20, "deliveryAddress": "The Chennai SilksNo. 1, G.S.T. Main RoadLakshman Nagar, ChromepetChennai, Tamil Nadu 600044"}', '{"id": "6228d1bf-0d61-4ef1-acff-c23553c7bf3e", "cgst": 68.85, "igst": 0, "sgst": 68.85, "type": "Sales Order", "status": "Ready for Shipment", "freight": 20, "taxType": "Exclusive", "otherGst": true, "roundOff": 0.2999999999999545, "taxRegNo": "33AAFFT0634G1ZJ", "createdAt": "2026-07-01T10:44:30.530Z", "createdBy": "7b93f413-f30d-4852-90f3-ac82fa7390ae", "deletedAt": null, "insurance": 10, "totalCost": 206.5, "updatedAt": "2026-07-01T10:46:50.375Z", "collectTax": true, "customerId": "c126bcd0-34e7-4da1-91c3-5d0f207ef1da", "freightGst": true, "grandTotal": 898, "loadingGst": true, "packingGst": true, "referenceNo": "CO-000001", "totalProfit": 543.5, "deliveryDate": "2026-07-01T00:00:00.000Z", "insuranceGst": true, "internalNote": null, "otherCharges": 20, "paymentTerms": "Paid", "tdsDeduction": 5, "discountValue": 10, "quotationNote": "1. Acceptance of